function() {
  // アプリが送る集計用URLを優先する。
  var pageLocation = {{DLV - page_location}};
  if (pageLocation) return pageLocation;
  // page_locationを送らない旧版のタブでも、IDと未知URLのpathを送らない。
  var family = {{DLV - route_family}};
  if (family === "not_found" || document.querySelector("[data-static-not-found]")) {
    return location.origin + "/404";
  }
  var templatedPaths = {
    shop_detail: "/manage/shops/:shopId",
    shiftboard: "/shifts/:recruitmentId/board",
    shift_export: "/shifts/:recruitmentId/export",
    staff_detail: "/staff/:personId",
    staff_shop: "/staff/:personId/shops/:shopId"
  };
  var pathname = location.pathname.toLowerCase();
  var templatedPath = templatedPaths[family];
  if (templatedPath) {
    return location.origin + (pathname.indexOf("/app/") === 0 ? "/app" : "") + templatedPath;
  }
  return location.origin + pathname;
}
